CREATE EXTENSION IF NOT EXISTS citext;
CREATE TYPE user_role AS ENUM ('STUDENT','STAFF','ADMIN');
CREATE TYPE issue_status AS ENUM ('OPEN','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED');
CREATE TABLE app_user(user_id BIGSERIAL PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email CITEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role user_role NOT NULL DEFAULT 'STUDENT',is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE building(building_id BIGSERIAL PRIMARY KEY,name VARCHAR(120) UNIQUE NOT NULL,campus_zone VARCHAR(80) NOT NULL);
CREATE TABLE room(room_id BIGSERIAL PRIMARY KEY,building_id BIGINT NOT NULL REFERENCES building ON DELETE RESTRICT,room_code VARCHAR(30) NOT NULL,floor_no SMALLINT NOT NULL CHECK(floor_no>=0),UNIQUE(building_id,room_code));
CREATE TABLE issue_category(category_id BIGSERIAL PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,sla_hours INTEGER NOT NULL CHECK(sla_hours BETWEEN 1 AND 720));
CREATE TABLE issue(issue_id BIGSERIAL PRIMARY KEY,reporter_id BIGINT NOT NULL REFERENCES app_user ON DELETE RESTRICT,room_id BIGINT NOT NULL REFERENCES room ON DELETE RESTRICT,category_id BIGINT NOT NULL REFERENCES issue_category ON DELETE RESTRICT,title VARCHAR(160) NOT NULL CHECK(length(trim(title))>=5),description TEXT NOT NULL CHECK(length(trim(description))>=10),priority SMALLINT NOT NULL CHECK(priority BETWEEN 1 AND 5),status issue_status NOT NULL DEFAULT 'OPEN',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE issue_assignment(assignment_id BIGSERIAL PRIMARY KEY,issue_id BIGINT NOT NULL REFERENCES issue ON DELETE CASCADE,staff_id BIGINT NOT NULL REFERENCES app_user,assigned_by BIGINT NOT NULL REFERENCES app_user,assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ);
CREATE UNIQUE INDEX one_active_assignment ON issue_assignment(issue_id) WHERE ended_at IS NULL;
CREATE TABLE resolution_record(resolution_id BIGSERIAL PRIMARY KEY,issue_id BIGINT UNIQUE NOT NULL REFERENCES issue ON DELETE CASCADE,resolved_by BIGINT NOT NULL REFERENCES app_user,resolution_note TEXT NOT NULL,labor_minutes INTEGER NOT NULL CHECK(labor_minutes>=0));
CREATE INDEX issue_queue_idx ON issue(status,created_at DESC); CREATE INDEX issue_room_cat_idx ON issue(room_id,category_id);
CREATE VIEW v_open_issue_queue AS SELECT i.issue_id,i.title,i.priority,i.status,i.created_at,b.name building,r.room_code,c.name category,u.full_name reporter FROM issue i JOIN room r USING(room_id) JOIN building b USING(building_id) JOIN issue_category c USING(category_id) JOIN app_user u ON u.user_id=i.reporter_id WHERE i.status IN ('OPEN','ASSIGNED','IN_PROGRESS');
CREATE FUNCTION touch_issue() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); NEW.version=OLD.version+1; RETURN NEW; END $$;
CREATE TRIGGER issue_touch BEFORE UPDATE ON issue FOR EACH ROW EXECUTE FUNCTION touch_issue();
CREATE FUNCTION resolve_issue(p_issue BIGINT,p_staff BIGINT,p_note TEXT,p_minutes INTEGER) RETURNS VOID LANGUAGE plpgsql AS $$ BEGIN UPDATE issue SET status='RESOLVED',resolved_at=now() WHERE issue_id=p_issue AND status IN ('ASSIGNED','IN_PROGRESS'); IF NOT FOUND THEN RAISE EXCEPTION 'Issue missing or not resolvable'; END IF; INSERT INTO resolution_record(issue_id,resolved_by,resolution_note,labor_minutes) VALUES(p_issue,p_staff,p_note,p_minutes); END $$;
